const rows = $input.all().map((item) => item.json);
if (rows.length === 0) return [];

const grouped = new Map();
for (const row of rows) {
  const key = row.supervisor_id || 'unassigned';
  const existing = grouped.get(key) || {
    supervisor_id: row.supervisor_id || null,
    supervisor_email: row.supervisor_email || null,
    interns: []
  };

  existing.interns.push({
    internship_id: row.internship_id,
    employee_id: row.employee_id,
    intern_name: `${row.first_name} ${row.last_name}`,
    weekly_hours: Number(row.weekly_hours || 0)
  });

  grouped.set(key, existing);
}

return Array.from(grouped.values()).map((value) => ({ json: value }));

const supervisor = $input.first().json;
const lines = (supervisor.interns || []).map((intern) => `- ${intern.intern_name}: ${intern.weekly_hours} hrs`).join('\n');
const total = (supervisor.interns || []).reduce((sum, intern) => sum + Number(intern.weekly_hours || 0), 0);

return [{
  json: {
    supervisor_email: supervisor.supervisor_email || $env.HR_NOTIFICATION_EMAIL || 'hr@snconnect.local',
    supervisor_id: supervisor.supervisor_id || null,
    lines,
    intern_count: supervisor.interns.length,
    total_hours: total
  }
}];

